function [r, t, dt, k_perp, df, L, N, info] = makeGrid(L,N)

dt = 2*L/N;
t = (-N/2:N/2-1)*dt;
df = 1/(2*L);
[Xv,Yv] = meshgrid(t,t);
kv = 2*pi*(-N/2:N/2-1)*df;
[Kxv,Kyv] = meshgrid(kv,kv);
k_perp = sqrt(Kxv.^2 + Kyv.^2);

r = sqrt(Xv.^2 + Yv.^2);
    info = struct('N', N, 'Lmax', max(t), 'dt', dt, 'df', df)
end

function [n1, n2, a1, L1] = components_step(n_core, n_background, a, L)
    n1 = n_core; 
    n2 = n_background; 
    L1 = L;
    a1 = a;
end

function [n3, L2] = components_CSF(n_silica, L)
    n3 = n_silica;
    L2 = L;
end

function [n4, D1, A1, a2, L3] = components_grin(n_core, Delta, alpha, a, L)
    n4 = n_core;
    D1 = Delta;
    A1 = alpha;
    L3 = L;
    a2 = a;
end


function [n5, L4] = components_material(n_material, L)
    n5 = n_material;
    L4 = L;
end

function [dz, ITR1, ITR2, ITR3, ITR4] = make_Z_space(dz, L1, L2, L3, L4)
    dz = dz;

    ITR1 = round(L1/dz);
    ITR2 = round(L2/dz);
    ITR3 = round(L3/dz);
    ITR4 = round(L4/dz);

    temp1 = L1 + L2 + L3 + L4;    
    temp2 = ITR1 + ITR2 + ITR3 + ITR4;

    info = struct('Total_Lenght', temp1, 'Total_Itr', temp2)
end

function [PSI1, k0, w0] = about_Glight(lambda0, w, r)
    k0 = 2*pi/lambda0;
    w0 = w;
    PSI1 = exp(-r.^2/w0^2);
end

function RIP1 =  make_stepRI_profile(n1, n2, a1, r)
    RIP1 = n2 + double(r < a1) * (n1 - n2);
end

function RIP2 =  make_grinRI_profile(n4, D1, A1, a2, r)
    n_cladding = n4*(1-2*D1)^0.5;
    n_core = n4*sqrt(1-2*D1*((r/a2).^A1));
    RIP2=n_core.*double(r < a2)+n_cladding.*double(r >= a2); 
end

function [HP1, HP2, HP3, HP4] = Kernel_HP(k0, k_perp, n2, n3, n4, D1, n5, dz)
    kbar_step = k0 * n2;
    kbar_CSF = k0 * n3;
        n_background_grin = n4*(1-2*D1)^0.5;
    kbar_grin = k0 * n_background_grin;
    kbar_mat = k0 * n5;

    HP1 = exp(1j*dz*(k_perp.^2)./( sqrt(kbar_step^2-k_perp.^2)+kbar_step) );
    HP2 = exp(1j*dz*(k_perp.^2)./( sqrt(kbar_CSF^2-k_perp.^2)+kbar_CSF) );
    HP3 = exp(1j*dz*(k_perp.^2)./( sqrt(kbar_grin^2-k_perp.^2)+kbar_grin) );
    HP4 = exp(1j*dz*(k_perp.^2)./( sqrt(kbar_mat^2-k_perp.^2)+kbar_mat) );
end

function [HM1, HM2] = Kernel_HM(RIP1, RIP2, n2, n4, D1, k0, dz)

        n_background_grin = n4*(1-2*D1)^0.5;

    delta_n_step = RIP1 - n2;
    delta_n_grin = RIP2 - n_background_grin;

    HM1 = exp(-1j*k0*delta_n_step*dz);
    HM2 = exp(-1j*k0*delta_n_grin*dz);

end

function HIST_xz = XZ_image(HP1, HP2, HP3, HP4, HM1, HM2, PSI1, ITR1, ITR2, ITR3, ITR4)

    HP1s = fftshift(HP1);
    HP2s = fftshift(HP2);
    HP3s = fftshift(HP3);
    HP4s = fftshift(HP4);

        temp_A = PSI1;

    temp = size(PSI1);    temp = temp(1, 1);
    HIST_xz_1 = zeros(temp, ITR1+1);
    HIST_xz_2 = zeros(temp, ITR2);
    HIST_xz_3 = zeros(temp, ITR3);
    HIST_xz_4 = zeros(temp, ITR4);

    HIST_xz_1(:,1) = PSI1(:,temp/2);
    for i = 2:ITR1+1
        temp_A = ifft2(fft2(temp_A.*HM1).*HP1s);
        HIST_xz_1(:,i) = temp_A(:,temp/2);
    end

    for i = 1:ITR2
        temp_A = ifft2(fft2(temp_A).*HP2s);
        HIST_xz_2(:,i) = temp_A(:,temp/2);
    end

    for i = 1:ITR3
        temp_A = ifft2(fft2(temp_A.*HM2).*HP3s);
        HIST_xz_3(:,i) = temp_A(:,temp/2);
    end

    for i = 1:ITR4
        temp_A = ifft2(fft2(temp_A).*HP4s);
        HIST_xz_4(:,i) = temp_A(:,temp/2);
    end

    HIST_xz = [HIST_xz_1, HIST_xz_2, HIST_xz_3, HIST_xz_4]

end
